-- Versioned test plans and their test cases (PLAN-001), with the minimal `runs` table they reference (ORCH owns
-- the full run model and extends `runs` in later migrations). Generated by `pnpm db:generate` from
-- src/schema/runs.ts and src/schema/test-plans.ts, then reviewed. Forward-only: never edit once applied.
-- `destructive` is storable but cannot be approved, executing or executed (CHECK, §8.3). An approved, executing or
-- executed case must carry its declared oracle (CHECK, §8.11). Composite (tenant_id, …) foreign keys stop a plan or
-- a case from pointing into another tenant (plain FK checks bypass RLS). Size backstop: 64 KiB per jsonb column;
-- the API layer (PLAN-005) enforces 16 KiB.
CREATE TABLE "runs" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"state" text DEFAULT 'draft' NOT NULL,
	"state_version" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "runs_tenant_id_id_unique" UNIQUE("tenant_id","id"),
	CONSTRAINT "runs_state_check" CHECK ("runs"."state" IN ('draft', 'preflight', 'recon', 'planning', 'awaiting_gate1', 'approved', 'executing', 'paused', 'validating', 'awaiting_gate3', 'released', 'reporting', 'completed', 'cancelled', 'killed', 'failed', 'expired'))
);
--> statement-breakpoint
ALTER TABLE "runs" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE TABLE "test_cases" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"test_plan_id" uuid NOT NULL,
	"class" text NOT NULL,
	"title" text NOT NULL,
	"owasp_refs" text[] DEFAULT '{}' NOT NULL,
	"wstg_refs" text[] DEFAULT '{}' NOT NULL,
	"asvs_refs" text[] DEFAULT '{}' NOT NULL,
	"cwe_candidates" text[] DEFAULT '{}' NOT NULL,
	"targets" jsonb NOT NULL,
	"roles" text[] DEFAULT '{}' NOT NULL,
	"budget" jsonb NOT NULL,
	"oracle" jsonb,
	"negative_control" jsonb,
	"status" text DEFAULT 'proposed' NOT NULL,
	"status_reason" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "test_cases_class_check" CHECK ("test_cases"."class" IN ('passive', 'active_safe', 'state_changing', 'destructive')),
	CONSTRAINT "test_cases_status_check" CHECK ("test_cases"."status" IN ('proposed', 'approved', 'removed', 'executing', 'executed', 'skipped', 'blocked', 'failed', 'model_declined', 'not_applicable')),
	CONSTRAINT "test_cases_title_check" CHECK (length("test_cases"."title") >= 1),
	CONSTRAINT "test_cases_targets_array_check" CHECK (jsonb_typeof("test_cases"."targets") = 'array' AND jsonb_array_length("test_cases"."targets") >= 1 AND octet_length("test_cases"."targets"::text) <= 65536),
	CONSTRAINT "test_cases_budget_object_check" CHECK (jsonb_typeof("test_cases"."budget") = 'object' AND octet_length("test_cases"."budget"::text) <= 65536),
	CONSTRAINT "test_cases_oracle_object_check" CHECK ("test_cases"."oracle" IS NULL OR (jsonb_typeof("test_cases"."oracle") = 'object' AND octet_length("test_cases"."oracle"::text) <= 65536)),
	CONSTRAINT "test_cases_negative_control_object_check" CHECK ("test_cases"."negative_control" IS NULL OR (jsonb_typeof("test_cases"."negative_control") = 'object' AND octet_length("test_cases"."negative_control"::text) <= 65536)),
	CONSTRAINT "test_cases_status_reason_check" CHECK ("test_cases"."status" NOT IN ('removed', 'skipped', 'blocked', 'failed', 'model_declined', 'not_applicable') OR "test_cases"."status_reason" IS NOT NULL),
	CONSTRAINT "test_cases_destructive_never_runs_check" CHECK ("test_cases"."class" <> 'destructive' OR "test_cases"."status" NOT IN ('approved', 'executing', 'executed')),
	CONSTRAINT "test_cases_oracle_required_check" CHECK ("test_cases"."status" NOT IN ('approved', 'executing', 'executed') OR "test_cases"."oracle" IS NOT NULL)
);
--> statement-breakpoint
ALTER TABLE "test_cases" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE TABLE "test_plans" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"run_id" uuid NOT NULL,
	"version" integer NOT NULL,
	"status" text DEFAULT 'draft' NOT NULL,
	"created_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "test_plans_run_id_version_unique" UNIQUE("run_id","version"),
	CONSTRAINT "test_plans_tenant_id_id_unique" UNIQUE("tenant_id","id"),
	CONSTRAINT "test_plans_version_check" CHECK ("test_plans"."version" >= 1),
	CONSTRAINT "test_plans_status_check" CHECK ("test_plans"."status" IN ('draft', 'proposed', 'approved', 'superseded'))
);
--> statement-breakpoint
ALTER TABLE "test_plans" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "test_cases" ADD CONSTRAINT "test_cases_test_plan_fk" FOREIGN KEY ("tenant_id","test_plan_id") REFERENCES "public"."test_plans"("tenant_id","id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "test_plans" ADD CONSTRAINT "test_plans_run_fk" FOREIGN KEY ("tenant_id","run_id") REFERENCES "public"."runs"("tenant_id","id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "runs_tenant_id_idx" ON "runs" USING btree ("tenant_id");--> statement-breakpoint
