CREATE INDEX "test_cases_status_idx" ON "test_cases" USING btree ("status");--> statement-breakpoint
CREATE INDEX "test_cases_class_idx" ON "test_cases" USING btree ("class");--> statement-breakpoint
CREATE INDEX "test_plans_tenant_id_idx" ON "test_plans" USING btree ("tenant_id");--> statement-breakpoint
