CREATE POLICY "test_plans_tenant_isolation" ON "test_plans" AS PERMISSIVE FOR ALL TO public USING (tenant_id = current_setting('app.tenant_id')::uuid) WITH CHECK (tenant_id = current_setting('app.tenant_id')::uuid);

-- Hand-written below (Drizzle models neither FORCE ROW LEVEL SECURITY, grants nor the updated_at triggers). Reviewed.
-- FORCE: the owner role is subject to the tenant policy too, so nothing reads across tenants.
ALTER TABLE "runs" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "test_plans" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "test_cases" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
-- The runtime role gets SELECT/INSERT/UPDATE only: no DELETE and no TRUNCATE, never PUBLIC. A plan version is
-- superseded, never removed, so the history of a run's plans is kept.
REVOKE ALL ON "runs", "test_plans", "test_cases" FROM PUBLIC;--> statement-breakpoint
REVOKE DELETE, TRUNCATE ON "runs", "test_plans", "test_cases" FROM bw_app;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON "runs" TO bw_app;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON "test_plans" TO bw_app;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON "test_cases" TO bw_app;--> statement-breakpoint
-- Keeps updated_at in step with every write (bw_set_updated_at: 0002_column_mixins).
CREATE TRIGGER runs_set_updated_at BEFORE UPDATE ON runs FOR EACH ROW EXECUTE FUNCTION bw_set_updated_at();--> statement-breakpoint
CREATE TRIGGER test_plans_set_updated_at BEFORE UPDATE ON test_plans FOR EACH ROW EXECUTE FUNCTION bw_set_updated_at();--> statement-breakpoint
CREATE TRIGGER test_cases_set_updated_at BEFORE UPDATE ON test_cases FOR EACH ROW EXECUTE FUNCTION bw_set_updated_at();
